                'consent': 'Onam',
                'ssc-board': 'GCKL',
                'ssc-board-preop': 'GCKL',
                'ssc-board-intraop': 'GCKL',
                'ssc-board-postop': 'GCKL',
                'hypothermia': 'Isı',
                'bleeding': 'Kanama',
                'fall': 'Düşme',
                'education': 'Eğitim',
