                'preop-medrec': 'İlaç',
                'preop-crossmatch': 'KAN',
                'preop-vte': 'VTE',
                'preop-anxiety': 'Anksiyete',
                'preop-delirium': 'Deliryum',
                'preop-clipper': 'Clipper',
                'preop-transfer': 'Transfer',
                'prep': 'Hazırlık',
                'prep-storage': 'Dolap',
                'hand-hygiene': 'El',
                'baseline-vitals': 'Monitör',
