            // ============================================================
            // KOLLAR — anatomik, doğal duruş, NORMAL POZ (rotasyonsuz)
            // ============================================================
            
            // SOL KOL: Yanında düz aşağı sarkmış (rest position)
            // Üst kol (omuzdan dirseğe)
            g.add(box(0.090, 0.30, 0.090, scrub, -0.235, 0.92, 0, { roughness: 0.60 }));
