            addObj(buildMiniStand(2.02, 0, 1.78, 0xd96371), 'Düşme Riski İşareti', 'Postop düşme riskini görünür kılan işaret yatak çevresi ve mobilizasyon hattı arasında konumlandırıldı.', { taskId: mob?.id, clinicalKey: 'postop-fall-risk' });
            addObj(buildTrayKit(3.95, 0, 0.86, 0x4cb88a), 'Taburculuk Hazırlık Paketi', 'Yara bakımı, ilaç, aktivite ve alarm bulgularına ilişkin taburculuk materyali aile bilgilendirme alanına yakın hazır tutulur.', { taskId: handoff?.id, clinicalKey: 'postop-discharge' });
            addObj(buildChecklistBoard(-5.95, 0, 3.55), 'GCKL Panosu', 'Postoperatif GCKL panosu; sol ön güvenlik lideri olarak SBAR teslim, solunum/oksijen, ağrı, kanama/dren, nörolojik durum ve mobilizasyon-güvenlik adımlarının ilerlemesini gösterir. Görevler faz listesinden tamamlandıkça bu pano entegre biçimde güncellenir.', { taskId: handoff?.id, clinicalKey: 'ssc-board-postop' });

            statusMarker(-4.70, 1.42, -1.40, handoff, 'SBAR',     { role:'pacu', priority:'critical', clinicalKey:'handoff' });
            if (resp)  statusMarker(0.86, 1.05, 0.05, resp, 'Solunum/O₂', { role:'pacu', priority:'critical', clinicalKey:'pacu-airway' });
            if (pain)  statusMarker(-0.28, 1.18, 0.22, pain, 'Ağrı',       { role:'pacu', priority:'active',   clinicalKey:'postop-pain-score' });
            if (drain) statusMarker(1.10, .62, 0.80,  drain, 'Dren',       { role:'pacu', priority:'active',   clinicalKey:'drain' });
            if (drain) statusMarker(1.62, 1.06, 0.90, drain, 'Kanama',     { role:'pacu', priority:'critical', clinicalKey:'bleeding', shortLabel:'Kanama' });
