            toast('info', App.aiMode ? '✨ AI Hasta: AÇIK' : 'AI Hasta: KAPALI', App.aiMode ? 'Diyaloglar ve analizler artık Gemini LLM tarafından üretilecek.' : 'Kural tabanlı mock yanıtlar gösterilecek.');
            renderTopbar();
