                const sprite = new THREE.Sprite(material); sprite.scale.set(2.25, .42, 1); sprite.position.set(x,y,z);
                addMotionProp(sprite); scheduleMotion({ type:'labelFade', prop:sprite, delay, duration }); return sprite;
